<section class="relatorio"><div class="section-head"><div><h2>Estoque físico</h2><p><?= (int)$result['total'] ?> produto(s) vinculados a contratos ativos. Saldo em unidades inteiras do próprio produto.</p></div></div>
<form method="get" action="<?= e(url('estoque')) ?>" class="mb-3"><label for="busca">Buscar produto ou contrato</label><div class="d-flex gap-2"><input id="busca" class="form-control" name="busca" value="<?= e($search) ?>"><button class="btn btn-primary">Buscar</button></div></form>
<div class="table-scroll"><table class="table"><thead><tr><th>Produto</th><th>Contrato</th><th>Saldo atual</th><th>Mínimo</th><th>Máximo</th><th>Situação</th><th></th></tr></thead><tbody>
<?php foreach ($result['items'] as $item): $balance=(int)$item['saldo']; $pending=(int)$item['estoque_inicializado']===0; ?><tr><td><?= e($item['nome_produto']) ?></td><td><?= e($item['titulo']) ?></td><td><?= $pending ? 'Pendente' : $balance.' '.e($item['unidade']) ?></td><td><?= $pending ? '—' : (int)$item['estoque_minimo'] ?></td><td><?= $pending ? '—' : (int)$item['estoque_maximo'] ?></td><td><?= $pending ? 'Abertura pendente' : ($balance===0 ? 'Sem saldo' : ($balance<=(int)$item['estoque_minimo'] ? 'Atenção: no mínimo ou abaixo' : 'Normal')) ?></td><td><a href="<?= e(url('contrato/detalhes/'.$item['id_pedido'])) ?>">Abrir</a> · <a href="<?= e(url('contrato/historico/'.$item['id'])) ?>">Histórico</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($result['items']===[]): ?><p>Nenhum produto encontrado.</p><?php endif; ?>
<nav aria-label="Páginas"><?php for ($p=1;$p<=$result['pages'];$p++): ?><a class="btn btn-sm <?= $p===$result['page'] ? 'btn-primary' : 'btn-outline-primary' ?>" href="<?= e(url('estoque?busca='.rawurlencode($search).'&pagina='.$p)) ?>"><?= $p ?></a> <?php endfor; ?></nav></section>
